  wallShape.moveTo(-W / 2, 0);
  wallShape.lineTo(W / 2, 0);
  wallShape.lineTo(W / 2, H3);
  wallShape.lineTo(-W / 2, H3);
  wallShape.lineTo(-W / 2, 0);
  const holePath = new Path();
  holePath.absarc(0, CY, R, 0, Math.PI * 2, true);
  wallShape.holes.push(holePath);
  const wg = new ExtrudeGeometry(wallShape, { depth: D2 - 16, bevelEnabled: true, bevelThickness: 8, bevelSize: 8, bevelOffset: -8, bevelSegments: 3, curveSegments: 96 });
