  wall.castShadow = true;
  wall.receiveShadow = true;
  wall.name = "vault wall";
  group.add(wall);
  const frame = new Mesh(new TorusGeometry(R + 40, 40, 32, 96), steel());
  frame.position.set(0, CY, 18);
  frame.name = "vault frame";
