      const v2 = countUp(f2, CNT2[0], CNT2[1], 0, 19e4);
      dc.update({ day0: "364", day1: "365", flip: t2, money: `\xA3${(Math.round(v2 / 1e3) * 1e3).toLocaleString("en-US")} A DAY`, lit: clamp01((f2 - (C0 - 2)) / 5) });
      ringC.update(f2, CNT2[1]);
