        const top = rest.y + 90, y2 = p2 < 0.7 ? slotW.y + (top - slotW.y) * q2 + 120 * Math.sin(Math.PI * q2) : top + (rest.y - top) * ((p2 - 0.7) / 0.3) ** 2;
        c2.group.position.set(x2, y2, z2);
        c2.group.rotation.set(1.2 * (1 - q2), k2 * 0.9, 0.6 * (1 - q2));
